"""Six original ordinary-DE constructions after honest old-family demotions.
Bounded finite candidates, not admitted records. No application writes.
"""
from common import *
reg=Registry('differential equations');register=reg.register
x,t,z=s.symbols('x t z',real=True)

@register('nonlinear-fast-nullcline-decay','fast-nullcline-tracking-asymptotic','Identify and control the fast deviation from the nullcline, prove its normalized tracking limit, and recover the slow algebraic decay.','The rejected reciprocal logarithmic relaxation is explicitly separable. This coupled system needs an invariant trapping region and an attracting ratio limit.',[{'m':m} for m in range(2,12)],'fast-slow-nullcline-tracking',('invariant regions','asymptotic integration'))
def tracking(m):
 a=(2*m)**(-1/(2*m))
 Q=T('Let the real solution have the displayed initial data. Find the limit.')+r'\quad x\prime=x^3-xy,\quad y\prime=-y+x^2+x^{'+L(2*m)+r'},\quad x(0)=\frac14,\quad y(0)=\frac1{16},\qquad\lim_{t\to\infty}t^{'+L(1/(2*m))+r'}x(t)=?'
 steps=[T('Subtract the fast nullcline and normalize its deviation: ')+r'z=y-x^2,\qquad w=z/x^{'+L(2*m)+r'}.',r'x\prime=-xz,\quad z\prime=-(1-2x^2)z+x^{'+L(2*m)+r'},\quad w\prime=1-w+2x^2w+'+L(2*m)+r'x^{'+L(2*m)+r'}w^2.',T('Initially the deviation is zero. Its derivative at zero is positive, so the deviation stays nonnegative and the positive first coordinate decreases. At the upper ratio barrier, ')+r'w=2\quad\Longrightarrow\quad w\prime\le-1+\frac14+'+L(8*m/4**(2*m))+r'<0.',r'0<x(t)\le\frac14,\quad0\le w(t)\le2.',T('These bounds give a global solution. If the decreasing first coordinate had a positive limit, the stable linear equation for the deviation would give a positive limiting deviation, forcing the first coordinate to decrease to zero. Thus the limit is zero.'),r'x(t)\to0,\qquad w\prime=1-w+o(1).',T('Variation of constants for this last scalar equation gives a ratio limit of one. Therefore ')+r'\frac{\mathrm d}{\mathrm dt}x^{-'+L(2*m)+r'}='+L(2*m)+r'w(t)\longrightarrow'+L(2*m)+r'.',T('Integrate and divide by time to obtain the requested normalized limit.')]
 xx,yy,ww=s.symbols('X Y W');xd=xx**3-xx*yy;yd=-yy+xx**2+xx**(2*m);zd=s.expand(yd-2*xx*xd);wd=s.expand((zd/xx**(2*m)-2*m*(yy-xx**2)*xd/xx**(2*m+1)).subs(yy,xx**2+ww*xx**(2*m)))
 checks=[check('independent deviation derivative',zd.subs(yy,z+xx**2),-(1-2*xx**2)*z+xx**(2*m)),check('independent normalized-ratio field',wd,1-ww+2*xx**2*ww+2*m*xx**(2*m)*ww**2),truth('strict upper ratio barrier',bool(-1+R(1,4)+8*m/4**(2*m)<0)),check('slow inverse-power derivative',s.diff(xx**(-2*m),xx)*(-ww*xx**(2*m+1)),2*m*ww)]
 pool=[(m**(-1/(2*m)),'omit the factor two in differentiating the inverse power'),((4*m)**(-1/(2*m)),'count the ratio limit twice'),((2*m)**(-1/m),'use the degree instead of twice the degree in the final root'),((2*m)**(-1/(2*m+2)),'retain an extra quadratic order in the slow field'),((2*m+2)**(-1/(2*m)),'integrate with an index two too large'),(s.Integer(1),'set the ratio limit directly equal to the amplitude constant')]
 return item(Q,a,pool,steps,checks,['Time is nonnegative; the given initial first coordinate is positive. The problem asks a limit of the actual coupled solution, not a formal nullcline substitution.'],['Positivity follows from x(t)=x(0) exp(-integral z), and the nonnegative z boundary points inward. The normalized ratio w is well-defined for finite time. The barrier calculation gives w<=2, hence bounded x,y and no finite escape. If x tends to ell>0, the stable scalar linear z equation converges to ell^(2m)/(1-2ell^2)>0, contradicting the positive limit for x. With x->0 and bounded w, the remainder in w prime=1-w+remainder tends to zero; the exponential convolution tends to zero by splitting its integral at a fixed large time. Cesaro integration of the inverse-power derivative gives the displayed limit.'],'coupled-nullcline-tracking-nonlinear-decay')

@register('Laguerre-zero-resolvent-limit','polynomial-ODE-Stieltjes-limit','Convert a polynomial ODE into an approximate algebraic equation for its zero resolvent; root positivity controls the derivative error and selects the correct branch.','Related globally to spectral Stieltjes transforms and Cauchy moment problems; unlike Hermite finite root moments or discriminants, this takes a growing-degree zero-distribution limit.',[{'c':str(R(j,2))} for j in range(1,11)],'logarithmic-derivative-resolvent-limit',('orthogonal polynomials','logarithmic derivatives','compactness'))
def laguerre(c):
 a=(s.sqrt((c+1)**2+4)-c-1)/2
 Q=T('For every positive integer ')+r'n,'+T(' let ')+r'P_n'+T(' be the monic polynomial of degree ')+r'n'+T(' satisfying the displayed equation. Its roots are listed with multiplicity. Find the limit.')+r'\quad tP_n\prime\prime+('+L(c)+r'n+1-t)P_n\prime+nP_n=0,\quad r_{n,1},\ldots,r_{n,n},\qquad\lim_{n\to\infty}\sum_{j=1}^{n}\frac1{n+r_{n,j}}=?'
 steps=[T('The polynomial is a monic generalized Laguerre polynomial. Rodrigues integration by parts shows orthogonality against every polynomial of degree below its degree for the positive weight ')+r't^{'+L(c)+r'n}e^{-t}\quad(t>0).',T('All roots are positive and simple: otherwise the product of the positive sign-changing factors would have lower degree and its weighted inner product with the polynomial would have one strict sign, contradicting orthogonality.'),r'F_n(z)=\frac{P_n\prime(nz)}{P_n(nz)}=\frac1n\sum_{j=1}^{n}\frac1{z-r_{n,j}/n}\quad(z<0).',r'zF_n(z)^2+\left('+L(c)+r'-z+\frac1n\right)F_n(z)+1+\frac znF_n\prime(z)=0.',T('At the fixed negative argument, positive roots give uniform bounds ')+r'-1\le F_n(-1)<0,\qquad |F_n\prime(-1)|\le1.',r'S_n=-F_n(-1)\in(0,1],\qquad S_n^2+('+L(c+1)+r')S_n-1=O(n^{-1}).',T('Every convergent subsequence must therefore approach the unique nonnegative root of this quadratic. Compactness then gives convergence of the entire sequence.')]
 checks=[]
 for nn in (3,5):
  poly=s.expand((-1)**nn*s.factorial(nn)*s.assoc_laguerre(nn,c*nn,t));F=s.diff(poly,t).subs(t,nn*z)/poly.subs(t,nn*z)
  checks.extend([check('independent finite polynomial ODE n='+str(nn),t*s.diff(poly,t,2)+(c*nn+1-t)*s.diff(poly,t)+nn*poly),check('exact logarithmic derivative equation n='+str(nn),z*F**2+(c-z+R(1,nn))*F+1+z*s.diff(F,z)/nn)])
 checks.extend([check('positive algebraic root',a*a+(c+1)*a,1),truth('root lies inside compact interval',bool(0<a<1))])
 pool=[((s.sqrt((c+1)**2+4)+c+1)/2,'select the reciprocal root by reversing the resolvent sign'),((s.sqrt((c-1)**2+4)-c+1)/2,'lose the negative evaluation argument in the linear term'),((s.sqrt((c+1)**2+4)-c-1)/4,'divide the quadratic root by two twice'),((s.sqrt((c+1)**2+8)-c-1)/2,'count the constant term twice'),(1/(c+1),'discard the nonlinear resolvent square'),(1/(c+2),'replace all roots by their average before taking reciprocals')]
 return item(Q,a,pool,steps,checks,['The monic ODE solution exists uniquely by coefficient comparison. The roots are proved positive, so no denominator in the question vanishes.'],['Rodrigues formula is proportional to t^(-alpha)e^t times the nth derivative of e^(-t)t^(n+alpha), with alpha=cn>0. Integrating against t^j for j<n transfers all n derivatives and gives zero; boundary terms vanish at both endpoints. The standard sign-change polynomial argument then proves n distinct positive roots. At z=-1 each resolvent term has magnitude at most one and each derivative term at most one, giving the explicit uniform error bound. The negative algebraic root is excluded by S_n>=0; uniqueness on [0,1] plus compactness proves the limit.'],'Laguerre-growing-degree-negative-resolvent-limit',sourceRecordIds=['q4-reference-dlmf-classical-orthogonality'])

@register('nonlinear-damping-Melnikov-bound','homoclinic-first-order-splitting','Recover the unperturbed homoclinic orbit, evaluate its nonlinear dissipative work and Fourier forcing, and apply the simple-zero criterion for the explicitly defined first-order function.','The homoclinic-mass family only integrates one orbit norm. This needs nonlinear damping work, phase-dependent forcing, and the distinction between a simple-zero threshold and an exact finite-perturbation claim.',[{'m':m} for m in range(1,11)],'Melnikov-energy-balance-and-Fourier-integral',('Hamiltonian energy','homoclinic trajectories','Fourier integrals'))
def melnikov(m):
 D=R(4,3)+2**(m+1)*s.factorial(m)*s.gamma(R(3,2))/s.gamma(m+R(5,2));D=s.simplify(D);C=s.sqrt(2)*s.pi/s.cosh(s.pi/2);a=D/C
 Q=r'x\prime\prime=x-x^3+\varepsilon\left[-(1+x^{'+L(2*m)+r'})x\prime+A\cos t\right],\qquad A>0.'+T('Let ')+r'x_h'+T(' be the positive unperturbed homoclinic orbit with its maximum at zero, and put ')+r'v_h=x_h\prime.'+T('Define the first-order Melnikov function by ')+r'M_A(\phi)=\int_{-\infty}^{\infty}v_h(t)\left[-(1+x_h(t)^{'+L(2*m)+r'})v_h(t)+A\cos(t+\phi)\right]\,\mathrm dt.'+T('Find ')+r'\inf\{A>0:M_A\textnormal{ has a simple real zero}\}.'
 steps=[T('Zero energy for the unperturbed equation gives the positive homoclinic orbit ')+r'x_h(t)=\sqrt2\,\operatorname{sech}t,\quad v_h(t)=-\sqrt2\,\operatorname{sech}t\tanh t,\quad\operatorname{sech}t=1/\cosh t.',T('For the dissipative part, substitute ')+r'u=\tanh t.'+r'\quad D=\int_{-1}^{1}2u^2\left[1+2^{'+L(m)+r'}(1-u^2)^{'+L(m)+r'}\right]\,\mathrm du='+L(D)+r'.',T('The Fourier transform follows by setting ')+r'v=e^{2t}'+T(' in the exponential transform of the hyperbolic secant and evaluating the beta integral: ')+r'\int_{-\infty}^{\infty}\operatorname{sech}t\cos t\,\mathrm dt=\frac\pi{\cosh(\pi/2)}.',T('Oddness removes the cosine-phase contribution of the velocity. Integration by parts supplies the sine-phase term.'),r'\int_{-\infty}^{\infty}v_h(t)\sin t\,\mathrm dt=-\frac{\sqrt2\pi}{\cosh(\pi/2)},\qquad M_A(\phi)=-'+L(D)+r'+'+L(C)+r'A\sin\phi.',T('There are simple zeros precisely when the oscillating amplitude exceeds the positive dissipative constant. At equality the zero is tangent, but equality is still the infimum.')]
 xx=s.sqrt(2)/s.cosh(t);u=s.symbols('u',real=True);checks=[check('homoclinic differential equation',s.diff(xx,t,2),xx-xx**3),check('homoclinic zero energy',s.diff(xx,t)**2/2-xx*xx/2+xx**4/4),check('independent polynomial damping-work integral',s.integrate(s.expand(2*u*u*(1+2**m*(1-u*u)**m)),(u,-1,1)),D),check('first-order amplitude balance',a*C,D),truth('strictly positive work and Fourier amplitude',bool(D>0 and C>0))]
 pool=[(R(4,3)/C,'discard the nonlinear damping work'),((D-R(4,3))/C,'discard the linear damping work'),(D/(2*C),'double the forcing Fourier amplitude'),(2*D/C,'halve the forcing Fourier amplitude'),(D*s.sinh(s.pi/2)/(s.sqrt(2)*s.pi),'use the odd hyperbolic kernel instead of the even one'),(D*s.cosh(s.pi/2)/s.pi,'omit the homoclinic square-root normalization')]
 return item(Q,a,pool,steps,checks,['Only the explicitly defined first-order Melnikov simple-zero criterion is asked. No exact threshold for chaos or transverse intersections at a fixed nonzero perturbation is asserted. The phase is real.'],['The orbit decays exponentially, so all work and Fourier integrals converge absolutely. The Fourier beta integral has complex parameter (1+i)/2 with real part one half; Euler reflection gives pi/cosh(pi/2). Integration by parts has vanishing boundary terms. The sine function has simple intersections with a horizontal level strictly between minus one and one; equality gives a double tangency. This proves the infimum directly from the definition without invoking any finite-epsilon dynamical conclusion.'],'Duffing-nonlinear-damping-first-order-Melnikov-infimum',sourceRecordIds=['q4-reference-homoclinic-method-context'])

@register('formal-Laurent-resonance-obstruction','nonlinear-ODE-resonance-compatibility','Find the resonant Laurent coefficient where the recursion loses its unknown; its compatibility condition selects the possible positive pole location.','Ordinary Taylor jet calculations determine each next coefficient. Here an integer resonance creates an obstruction, and a free coefficient appears only after compatibility is proved.',[{'m':m} for m in range(3,13)],'formal-Laurent-dominant-balance-and-resonance',('formal power series','nonlinear coefficient recursions'))
def resonance(m):
 a=(2/(m*(m-1)))**(1/(m-2))
 Q=r'y\prime\prime=6y^2+x^{'+L(m)+r'}-x^2.'+T('For which positive real number ')+r'a'+T(' does this equation admit a formal Laurent series of the displayed form, with no logarithmic terms? No convergence of the formal series is required.')+r'\quad y(x)=(x-a)^{-2}+\sum_{j=-1}^{\infty}c_j(x-a)^j.'
 steps=[T('Set ')+r'z=x-a,\quad g(x)=x^{'+L(m)+r'}-x^2.'+T('The leading terms already balance. Comparing the next three negative powers gives ')+r'c_{-1}=c_0=c_1=0.',r'-10c_2=g(a),\qquad-6c_3=g\prime(a).',T('At the next power the coefficient of the new unknown cancels exactly: ')+r'12c_4=12c_4+\frac12g\prime\prime(a).',r'g\prime\prime(a)=0\quad\Longleftrightarrow\quad '+L(m*(m-1))+r'a^{'+L(m-2)+r'}-2=0.',T('This equation has exactly one positive root. Once it holds, the resonant coefficient is free, and all later coefficients are recursively determined because ')+r'j(j-1)-12=(j-4)(j+3)\ne0\quad(j\ge5).',T('Thus compatibility is sufficient for a formal Laurent solution of every order, not merely necessary through the displayed coefficients.')]
 aa=s.symbols('a',positive=True);zz=s.symbols('z');c2,c3,c4=s.symbols('c2 c3 c4');Y=zz**-2+c2*zz**2+c3*zz**3+c4*zz**4;res=s.expand(s.diff(Y,zz,2)-6*Y**2-((aa+zz)**m-(aa+zz)**2));checks=[check('constant coefficient of independent Laurent substitution',res.coeff(zz,0),-10*c2-aa**m+aa*aa),check('linear coefficient of independent Laurent substitution',res.coeff(zz,1),-6*c3-m*aa**(m-1)+2*aa),check('resonance compatibility coefficient',res.coeff(zz,2),1-m*(m-1)*aa**(m-2)/2),check('positive compatibility root',m*(m-1)*a**(m-2),2),check('later coefficient multiplier factorization',x*(x-1)-12,(x-4)*(x+3))]
 pool=[(s.Integer(1),'require the forcing value rather than its second derivative to vanish'),((2/m)**(1/(m-2)),'omit the second derivative falling-factorial factor'),((1/(m*(m-1)))**(1/(m-2)),'lose the factorial two in the Taylor coefficient'),((2/(m*(m-1)))**(1/(m-1)),'solve with the wrong remaining power'),((4/(m*(m-1)))**(1/(m-2)),'count the quadratic forcing derivative twice'),(s.Integer(0),'select a nonpositive candidate without checking the quadratic forcing term')]
 return item(Q,a,pool,steps,checks,['The series is formal about a strictly positive real pole; its coefficients are real. Existence means coefficientwise satisfaction with no logarithmic powers. Analytic convergence is expressly outside the claim.'],['Substitution in the formal Laurent ring gives a triangular recursion. The negative coefficients -1,0,1 vanish. The coefficient at power two has zero multiplier for c4 and imposes g second derivative(a)=0. For every j>=5 the multiplier (j-4)(j+3) is nonzero, and the remaining terms depend only on already known coefficients and the polynomial forcing. Therefore arbitrary c4 extends uniquely to all later orders. The finite exact substitutions verify the actual resonant obstruction for each displayed polynomial.'],'formal-Laurent-pole-resonance-location')

@register('long-time-nonlinear-damping-average','uniform-long-time-action-averaging','Pass to amplitude and phase, remove the mean-zero fast drift with a bounded periodic corrector, and justify a uniform slow-time limit before evaluating the envelope.','The boundary-layer family was demoted because its linear solution is explicit. This weakly damped nonlinear oscillator needs an error bound over a time interval growing like the reciprocal perturbation.',[{'m':m} for m in range(1,11)],'action-angle-averaging-with-periodic-corrector',('polar coordinates','periodic averaging','Gronwall estimate'))
def averaging(m):
 C=s.factorial(2*m)/(2*4**m*s.factorial(m)*s.factorial(m+1));a=(1+2*m*C)**(-1/(2*m))
 Q=r'x_\varepsilon\prime\prime+x_\varepsilon+\varepsilon x_\varepsilon^{'+L(2*m)+r'}x_\varepsilon\prime=0,\quad x_\varepsilon(0)=1,\quad x_\varepsilon\prime(0)=0,\quad\varepsilon>0.'+T('Find the slow-time amplitude limit ')+r'\lim_{\varepsilon\downarrow0}\sqrt{x_\varepsilon(1/\varepsilon)^2+x_\varepsilon\prime(1/\varepsilon)^2}.'
 steps=[r'x=r\cos\theta,\quad x\prime=-r\sin\theta,\quad r(0)=1,\quad\theta(0)=0.',r'r\prime=-\varepsilon r^{'+L(2*m+1)+r'}F(\theta),\quad F(\theta)=\cos^{'+L(2*m)+r'}\theta\sin^2\theta,',r'\theta\prime=1-\varepsilon r^{'+L(2*m)+r'}\cos^{'+L(2*m+1)+r'}\theta\sin\theta.',T('On slow times between zero and one, energy dissipation and the elementary differential inequality give ')+r'(1+'+L(2*m)+r')^{-'+L(1/(2*m))+r'}\le r\le1.',r'\overline F=\frac1{2\pi}\int_0^{2\pi}F(\theta)\,\mathrm d\theta=\frac{(2m)!}{2\cdot4^m m!(m+1)!}\Bigg|_{m='+L(m)+r'}='+L(C)+r'.',T('Choose a bounded periodic primitive of the mean-zero part and correct the amplitude: ')+r'G\prime(\theta)=F(\theta)-\overline F,\quad\widetilde r=r+\varepsilon r^{'+L(2*m+1)+r'}G(\theta).',T('Direct differentiation cancels the oscillating drift. With slow time ')+r'\tau=\varepsilon t'+T(', the corrected variable satisfies uniformly ')+r'\frac{\mathrm d\widetilde r}{\mathrm d\tau}=-'+L(C)+r'\widetilde r^{'+L(2*m+1)+r'}+O(\varepsilon),\quad0\le\tau\le1.',T('Gronwall comparison gives uniform convergence to the averaged solution ')+r'R(\tau)=\left(1+'+L(2*m*C)+r'\tau\right)^{-'+L(1/(2*m))+r'}.',T('Evaluate at slow time one.')]
 w=s.symbols('w',nonzero=True);cos=(w+1/w)/2;sin=(w-1/w)/(2*s.I);constant=s.expand(cos**(2*m)*sin*sin).coeff(w,0);rr,cc,ss=s.symbols('r c q');xd=-rr*ss;vd=-rr*cc-s.Symbol('eps')*(rr*cc)**(2*m)*(-rr*ss);tau=s.symbols('tau',nonnegative=True);Rr=(1+2*m*C*tau)**(-1/(2*m))
 checks=[check('independent Fourier constant term for averaging',constant,C),check('averaged scalar differential equation',s.diff(Rr,tau),-C*Rr**(2*m+1)),check('averaged initial value',Rr.subs(tau,0),1),check('requested slow-time evaluation',Rr.subs(tau,1),a),truth('positive averaging constant',bool(C>0))]
 pool=[((1+4*m*C)**(-1/(2*m)),'double the averaged dissipative coefficient'),((1+m*C)**(-1/(2*m)),'lose the factor two from the inverse-amplitude power'),((1+2*m*C)**(-1/m),'use the energy exponent for the amplitude'),((1+2*m*C)**(-1/(2*m+2)),'retain two extra powers in the envelope'),(s.exp(-C),'linearize the amplitude damping over the whole slow interval'),((1+2*m)**(-1/(2*m)),'replace the oscillatory damping factor by its maximum')]
 return item(Q,a,pool,steps,checks,['The limit is taken through positive perturbations. The Euclidean phase-space amplitude is requested, not the phase or the instantaneous displacement. The slow observation time is exactly the reciprocal perturbation.'],['The nonnegative energy derivative gives a global bounded solution. The inequality r prime>=-epsilon*r^(2m+1) keeps r uniformly bounded away from zero for 0<=epsilon*t<=1. The amplitude/phase fields and their derivatives are therefore uniformly bounded on a fixed compact annulus. F minus its mean has a bounded smooth periodic primitive G. Differentiating the near-identity correction in original time gives -epsilon*mean(F)*r^(2m+1)+O(epsilon squared), since theta prime=1+O(epsilon) and r prime=O(epsilon). Dividing by epsilon and replacing r by the corrected radius costs only O(epsilon). The scalar averaged field is Lipschitz on the compact range; Gronwall gives an O(epsilon) error uniformly on the complete slow interval. Thus the growing observation time is covered, rather than justified by a formal pointwise average.'],'weak-nonlinear-damping-uniform-slow-time-amplitude',sourceRecordIds=['q4-reference-periodic-averaging-context'])

@register('Riccati-turning-point-connection','turning-point-recessive-branch-connection','Linearize the Riccati equation, select its recessive solution from the negative-time asymptotic, and match both small-argument Bessel powers to obtain a connection coefficient.','Unlike Bessel-zero normalization, this is a turning-point branch selection and Gamma connection constant. The forcing degree changes the local singular geometry and cannot be removed by a scalar time change.',[{'n':n} for n in range(1,20,2)],'Riccati-linearization-and-recessive-connection',('linear second-order equations','modified Bessel connection formulas','Gamma function'))
def turning(n):
 nu=1/(n+2);alpha=(n+2)/2;a=-(n+2)**(1-2*nu)*s.gamma(1-nu)/s.gamma(nu)
 Q=T('For each positive ')+r'\varepsilon,'+T(' let ')+r'y_\varepsilon'+T(' be the real solution on the negative half-line selected by the displayed asymptotic condition, continued to zero. Find the limit. The Gamma function is defined by the displayed integral.')+r'\quad\varepsilon y_\varepsilon\prime=t^{'+L(n)+r'}+y_\varepsilon^2,\qquad \frac{y_\varepsilon(t)}{-(-t)^{'+L(n/2)+r'}}\longrightarrow1\quad(t\to-\infty),\qquad\lim_{\varepsilon\downarrow0}\varepsilon^{-'+L(n/(n+2))+r'}y_\varepsilon(0)=?,\quad\Gamma(a)=\int_0^\infty u^{a-1}e^{-u}\,\mathrm du\ (a>0).'
 steps=[T('Scale the turning point and make the logarithmic-derivative substitution: ')+r't=\varepsilon^{'+L(2/(n+2))+r'}s,\quad y_\varepsilon=\varepsilon^{'+L(n/(n+2))+r'}Y(s),\quad Y=-u\prime/u.',r'Y\prime=s^{'+L(n)+r'}+Y^2,\qquad u\prime\prime+s^{'+L(n)+r'}u=0.',T('For negative scaled time put ')+r'v=-s>0,\quad\nu='+L(nu)+r',\quad z=\frac2{'+L(n+2)+r'}v^{'+L(alpha)+r'}.',T('The substitution ')+r'u(v)=\sqrt v\,W(z)'+T(' gives the modified Bessel equation ')+r'z^2W\prime\prime+zW\prime-(z^2+\nu^2)W=0.',T('The negative attracting asymptotic selects the positive recessive solution ')+r'u(v)=\sqrt v\,K_\nu(z).'+T(' Here ')+r'K_\nu'+T(' denotes the exponentially decaying real solution of the modified Bessel equation, up to its standard normalization.'),T('The two leading powers in its small positive argument expansion give ')+r'u(v)=A+Bv+o(v),\quad A=\tfrac12\Gamma(\nu)('+L(n+2)+r')^\nu,\quad B=\tfrac12\Gamma(-\nu)('+L(n+2)+r')^{-\nu}.',T('The derivative with respect to scaled time has the opposite sign from the derivative in the positive variable. Hence ')+r'Y(0)=\frac BA=('+L(n+2)+r')^{-2\nu}\frac{\Gamma(-\nu)}{\Gamma(\nu)}=-('+L(n+2)+r')^{1-2\nu}\frac{\Gamma(1-\nu)}{\Gamma(\nu)}.',T('The scaling is exact, so this is also the normalized limit in the question.')]
 v=s.symbols('v',positive=True);zv=v**alpha/alpha
 checks=[check('Bessel second derivative coefficient',s.sqrt(v)*s.diff(zv,v)**2,alpha**2*v**(-R(3,2))*zv*zv),check('Bessel first derivative coefficient',s.diff(zv,v)/s.sqrt(v)+s.sqrt(v)*s.diff(zv,v,2),alpha**2*v**(-R(3,2))*zv),check('Bessel zeroth coefficient',-R(1,4)*v**(-R(3,2))-v**(n+R(1,2)),-alpha**2*v**(-R(3,2))*(zv*zv+nu*nu)),check('independent I-minus/I-plus connection coefficient',-(n+2)**(-2*nu)*s.gamma(1-nu)/s.gamma(1+nu),a),truth('connection exponents are nonintegral and integrable',bool(0<nu<1))]
 pool=[(-a,'reverse the time derivative when changing to the positive variable'),(a/2,'lose one of the two leading connection coefficients'),(2*a,'count the two power branches twice'),(-(n+2)**(1-2*nu)*s.gamma(nu)/s.gamma(1-nu),'invert the Gamma connection ratio'),(-s.gamma(1-nu)/s.gamma(nu),'omit the turning-point argument scale'),(-(n+2)**(1+2*nu)*s.gamma(1-nu)/s.gamma(nu),'reverse the power of the Bessel argument scale')]
 return item(Q,a,pool,steps,checks,['The displayed odd power of time gives a recessive positive linear solution on negative time. The asymptotic selects its logarithmic derivative uniquely; no arbitrary initial value at a finite negative time is imposed.'],['For v>0 the linear equation is u_vv-v^n u=0. The modified-Bessel substitution is verified coefficientwise. The positive recessive K solution behaves like a positive multiple of z^(-1/2)exp(-z); its logarithmic derivative has the required negative Riccati asymptotic. Any nonzero growing I component gives the opposite leading logarithmic-derivative sign, so the branch is unique up to an irrelevant multiplier. Positivity prevents poles on negative time. For 0<nu<1, the exact connection K_nu=pi*(I_-nu-I_nu)/(2 sin(pi nu)) and the entire defining I series give the two displayed powers, with a differentiable remainder o(v); higher terms have powers at least n+2. The constant A is positive, so continuation to zero is regular. Gamma recurrence converts the negative Gamma argument to the positive arguments explicitly defined in the prompt.'],'Riccati-odd-turning-point-Gamma-connection',sourceRecordIds=['q4-reference-dlmf-modified-Bessel-connection'])

catalog=reg.catalog;build=reg.build;verify=reg.verify;all_candidates=reg.all_candidates
if __name__=='__main__':
 import json,hashlib
 from pathlib import Path
 p=Path(__file__).resolve().parent;rows=[];errors=[]
 for f in catalog():
  for i in range(f['instanceCount']):
   try:rows.append(build(f['familyId'],i))
   except Exception as e:errors.append({'familyId':f['familyId'],'instanceIndex':i,'error':repr(e)})
  print(f['familyId'],len(rows),'records;',len(errors),'errors',flush=True)
 temp=p/'ode-gap-candidates.jsonl.tmp';temp.write_text(''.join(json.dumps(r,sort_keys=True,default=str)+'\n' for r in rows));temp.replace(p/'ode-gap-candidates.jsonl')
 samples=[{k:r[k] for k in ['familyId','instanceIndex','statement','choices','parameters']} for r in rows if r['instanceIndex']==0]
